<script setup lang="ts">import{computed}from'vue';import{useAppStore}from'../stores/app';import{chapters}from'../data/chapters';import{Flame,BookOpen,RotateCcw,ChevronRight}from'@lucide/vue';import StatBar from'../components/StatBar.vue';import EmmaPortrait from'../components/EmmaPortrait.vue';const store=useAppStore();const greeting=computed(()=>{const h=new Date().getHours();return h<11?["Good morning! Did you sleep well?",'おはよう！よく眠れた？']:h<18?["Welcome home! How was your day?",'おかえり！今日はどうだった？']:["You’re back! I was hoping to see you.",'おかえり！会えるかなって思ってた。']});const chapter=computed(()=>chapters[store.currentChapter-1]);const level=computed(()=>store.s.xp<50?'Beginner A1':store.s.xp<120?'Elementary A2':'Pre-intermediate B1')</script>
<template><section class="page home"><header class="home-head"><div><small>WELCOME BACK</small><h2>{{store.s.name}} <span>さん</span></h2></div><div class="streak"><Flame :size="17"/> {{store.s.studyDays}} days</div></header><div class="hero-card"><div class="hero-copy"><span class="online">● ONLINE</span><h2>“{{greeting[0]}}”</h2><p>{{greeting[1]}}</p></div><EmmaPortrait expression="smile"/></div><div class="chapter-card"><div><p>NOW PLAYING · CHAPTER {{chapter.id}}</p><h3>{{chapter.title}}</h3><small>{{chapter.subtitle}}</small></div><div class="round-progress">{{Math.min(100,store.s.xp)}}<small>XP</small></div></div><div class="level-row"><div><small>ENGLISH LEVEL</small><b>{{level}}</b></div><div><small>TODAY</small><b>{{store.s.lastStudyDate? '1 lesson':'0 / 1'}}</b></div></div><div class="card relationship"><div class="section-title"><h3>ふたりの関係</h3><span>{{store.relationship}}</span></div><StatBar label="Affection" :value="store.s.affection" icon="♥"/><StatBar label="Trust" :value="store.s.trust" icon="✦" color="#8b82dc"/></div><RouterLink class="primary story-btn" :to="`/conversation/${chapter.id}`"><BookOpen/> ストーリーを進める <ChevronRight/></RouterLink><RouterLink class="secondary" to="/review"><RotateCcw/> 復習する</RouterLink></section></template>
